<?php
declare(strict_types=1);
require_once __DIR__ . '/accounts_common.php';
$user=qbook_require_user();qbook_require_role($user,['ADMIN']);production_require_method('POST');$input=production_input();
accounts_endpoint(function() use($user,$input): array {$name=production_clean_text($input['canonical_name']??'',200,'SUPPLIER_REQUIRED');$normalized=accounts_normalized_name($name);$db=production_db();return accounts_transaction($db,function() use($db,$user,$input,$name,$normalized): array {$existing=$db->prepare("SELECT id FROM qbook_suppliers WHERE normalized_name=? UNION SELECT supplier_id AS id FROM qbook_supplier_aliases WHERE normalized_alias=?");$existing->execute([$normalized,$normalized]);if($existing->fetch())accounts_fail('SUPPLIER_NAME_OR_ALIAS_CONFLICT',409);$db->prepare("INSERT INTO qbook_suppliers(canonical_name,normalized_name,contact_person,phone,email,address,supplier_type,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?)")->execute([$name,$normalized,production_clean_text($input['contact_person']??'',200,'INVALID_CONTACT',false)?:null,production_clean_text($input['phone']??'',80,'INVALID_PHONE',false)?:null,production_clean_text($input['email']??'',255,'INVALID_EMAIL',false)?:null,production_clean_text($input['address']??'',500,'INVALID_ADDRESS',false)?:null,production_clean_text($input['supplier_type']??'',100,'INVALID_SUPPLIER_TYPE',false)?:null,(int)$user['id'],(int)$user['id']]);$id=(int)$db->lastInsertId();foreach(($input['aliases']??[]) as $alias){$aliasName=production_clean_text($alias,200,'INVALID_SUPPLIER_ALIAS');$aliasNormalized=accounts_normalized_name($aliasName);$conflict=$db->prepare("SELECT id FROM qbook_suppliers WHERE normalized_name=?");$conflict->execute([$aliasNormalized]);if($conflict->fetch())accounts_fail('SUPPLIER_NAME_OR_ALIAS_CONFLICT',409);$db->prepare("INSERT INTO qbook_supplier_aliases(supplier_id,alias_name,normalized_alias,created_by) VALUES(?,?,?,?)")->execute([$id,$aliasName,$aliasNormalized,(int)$user['id']]);}accounts_audit($db,$user,'SUPPLIER_CREATED','SUPPLIER',$id,['canonical_name'=>$name]);return ['supplier'=>['id'=>$id,'canonical_name'=>$name,'is_active'=>1]];});});
